// === CHECK WATERSPOUT ACTUAL PARENT ===
var allGOs = Resources.FindObjectsOfTypeAll<GameObject>();
foreach(var go in allGOs){
    if(go.scene.name!="Game_Garden") continue;
    if(go.name=="WaterSpout"){
        var parent = go.transform.parent;
        Debug.Log("WaterSpout direct parent: "+(parent!=null ? parent.gameObject.name+" worldPos="+parent.position : "ROOT"));
        var pp = parent!=null ? parent.parent : null;
        Debug.Log("WaterSpout grandparent: "+(pp!=null ? pp.gameObject.name : "ROOT"));
    }
}

// === FIX 1: RehabCanvas scale (was 0,0,0 — should be 0.002) ===
var rehabCanvas = GameObject.Find("RehabCanvas");
if(rehabCanvas!=null){
    rehabCanvas.transform.localScale = new Vector3(0.002f, 0.002f, 0.002f);
    rehabCanvas.transform.position = new Vector3(0f, 1.6f, -3.2f);
    rehabCanvas.transform.eulerAngles = new Vector3(0f, 0f, 0f);
    EditorUtility.SetDirty(rehabCanvas);
    Debug.Log("RehabCanvas fixed: scale=0.002, pos=(0,1.6,-3.2), rot=0");
} else Debug.LogError("RehabCanvas NOT FOUND");

// === FIX 2: ScoreCanvas Z scale (was 0 — should be 0.002) ===
var scoreCanvas = GameObject.Find("ScoreCanvas");
if(scoreCanvas!=null){
    scoreCanvas.transform.localScale = new Vector3(0.01f, 0.45f, 0.002f);
    EditorUtility.SetDirty(scoreCanvas);
    Debug.Log("ScoreCanvas fixed: scale=(0.01,0.45,0.002)");
} else Debug.LogError("ScoreCanvas NOT FOUND");

// === FIX 3: WateringCup on floor (Y=0) — raise to table height ===
var waterCup = GameObject.Find("WateringCup");
if(waterCup!=null){
    var pos = waterCup.transform.position;
    Debug.Log("WateringCup current world pos: "+pos+" parent: "+(waterCup.transform.parent!=null ? waterCup.transform.parent.name : "ROOT"));
    // Only raise if Y is at floor level
    if(pos.y < 0.5f){
        waterCup.transform.position = new Vector3(pos.x, 0.85f, pos.z);
        EditorUtility.SetDirty(waterCup);
        Debug.Log("WateringCup raised to Y=0.85 (table height)");
    } else Debug.Log("WateringCup already at reasonable height: "+pos.y);
}

Debug.Log("All fixes applied.");
